class TreeNode {
    constructor(
        public left: TreeNode | null,
        public right: TreeNode | null
    ) {}
}

function makeTree(depth: number): TreeNode {
    if (depth <= 0) {
        return new TreeNode(null, null);
    }

    return new TreeNode(
        makeTree(depth - 1),
        makeTree(depth - 1)
    );
}

function itemCheck(node: TreeNode): number {
    if (node.left === null) {
        return 1;
    }

    return 1 + itemCheck(node.left) + itemCheck(node.right!);
}

function checkTemporaryTree(depth: number): number {
    return itemCheck(makeTree(depth));
}

const n = Number.parseInt(process.argv[2], 10);
const minDepth = 4;
const stretchDepth = n + 1;
const output: string[] = [];

output.push(
    `stretch tree of depth ${stretchDepth}\t check: ${checkTemporaryTree(stretchDepth)}`
);

const longLivedTree = makeTree(n);

for (let depth = minDepth; depth <= n; depth += 2) {
    const iterations = Math.pow(2, n - depth + minDepth);
    let check = 0;

    for (let i = 0; i < iterations; i++) {
        check += checkTemporaryTree(depth);
    }

    output.push(`${iterations}\t trees of depth ${depth}\t check: ${check}`);
}

output.push(
    `long lived tree of depth ${n}\t check: ${itemCheck(longLivedTree)}`
);

console.log(output.join("\n"));
