import * as fs from "fs";

const MODULUS = 139968;
const MULTIPLIER = 3877;
const INCREMENT = 29573;
const LINE_WIDTH = 60;

const n = Number.parseInt(process.argv[2], 10);

const ALU =
    "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
    "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
    "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
    "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
    "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

const nextSeed = new Int32Array(MODULUS);
for (let seed = 0; seed < MODULUS; seed++) {
    nextSeed[seed] = (seed * MULTIPLIER + INCREMENT) % MODULUS;
}

function makeLookup(symbols: string, probabilities: readonly number[]): Uint8Array {
    const cumulative = new Float64Array(probabilities.length);
    let sum = 0;

    for (let i = 0; i < probabilities.length; i++) {
        sum += probabilities[i];
        cumulative[i] = sum;
    }

    const lookup = new Uint8Array(MODULUS);

    for (let value = 0; value < MODULUS; value++) {
        const r = value / MODULUS;
        let index = 0;

        while (
            index + 1 < cumulative.length &&
            !(cumulative[index] > r)
        ) {
            index++;
        }

        lookup[value] = symbols.charCodeAt(index);
    }

    return lookup;
}

const iubLookup = makeLookup(
    "acgtBDHKMNRSVWY",
    [
        0.27, 0.12, 0.12, 0.27,
        0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
        0.02, 0.02, 0.02, 0.02, 0.02
    ]
);

const homoLookup = makeLookup(
    "acgt",
    [
        0.3029549426680,
        0.1979883004921,
        0.1975473066391,
        0.3015094502008
    ]
);

function writeBuffer(buffer: Buffer, length: number = buffer.length): void {
    let offset = 0;

    while (offset < length) {
        offset += fs.writeSync(1, buffer, offset, length - offset);
    }
}

function writeText(text: string): void {
    writeBuffer(Buffer.from(text, "ascii"));
}

function makeAluTemplate(symbolCount: number): Buffer {
    const output = Buffer.allocUnsafe(symbolCount + symbolCount / LINE_WIDTH);
    let outputPosition = 0;
    let aluPosition = 0;

    for (let generated = 0; generated < symbolCount;) {
        for (let column = 0; column < LINE_WIDTH; column++) {
            output[outputPosition++] = ALU.charCodeAt(aluPosition++);
            if (aluPosition === ALU.length) {
                aluPosition = 0;
            }
            generated++;
        }
        output[outputPosition++] = 10;
    }

    return output;
}

function makeRandomTemplate(
    symbolCount: number,
    lookup: Uint8Array,
    initialSeed: number
): Buffer {
    const output = Buffer.allocUnsafe(symbolCount + symbolCount / LINE_WIDTH);
    let outputPosition = 0;
    let seed = initialSeed;

    for (let generated = 0; generated < symbolCount;) {
        for (let column = 0; column < LINE_WIDTH; column++) {
            seed = nextSeed[seed];
            output[outputPosition++] = lookup[seed];
            generated++;
        }
        output[outputPosition++] = 10;
    }

    return output;
}

function emitWrappedTemplate(
    template: Buffer,
    templateSymbols: number,
    totalSymbols: number
): void {
    const fullTemplates = Math.floor(totalSymbols / templateSymbols);
    const remainingSymbols = totalSymbols - fullTemplates * templateSymbols;

    for (let i = 0; i < fullTemplates; i++) {
        writeBuffer(template);
    }

    if (remainingSymbols === 0) {
        return;
    }

    const completeLines = Math.floor(remainingSymbols / LINE_WIDTH);
    const trailingSymbols = remainingSymbols % LINE_WIDTH;
    const prefixBytes =
        completeLines * (LINE_WIDTH + 1) + trailingSymbols;

    writeBuffer(template, prefixBytes);

    if (trailingSymbols !== 0) {
        writeText("\n");
    }
}

function advanceSeed(seed: number, draws: number): number {
    let remaining = draws % MODULUS;

    while (remaining-- > 0) {
        seed = nextSeed[seed];
    }

    return seed;
}

const aluTemplateSymbols = ALU.length * LINE_WIDTH * 60;
const randomTemplateSymbols = 1_399_680;

writeText(">ONE Homo sapiens alu\n");
const aluTemplate = makeAluTemplate(aluTemplateSymbols);
emitWrappedTemplate(aluTemplate, aluTemplateSymbols, 2 * n);

let seed = 42;

writeText(">TWO IUB ambiguity codes\n");
const iubTemplate = makeRandomTemplate(randomTemplateSymbols, iubLookup, seed);
emitWrappedTemplate(iubTemplate, randomTemplateSymbols, 3 * n);
seed = advanceSeed(seed, 3 * n);

writeText(">THREE Homo sapiens frequency\n");
const homoTemplate = makeRandomTemplate(randomTemplateSymbols, homoLookup, seed);
emitWrappedTemplate(homoTemplate, randomTemplateSymbols, 5 * n);
