const DT = 0.01;

const masses = [
    SOLAR_MASS,
    9.54791938424326609e-4 * SOLAR_MASS,
    2.85885980666130812e-4 * SOLAR_MASS,
    4.36624404335156298e-5 * SOLAR_MASS,
    5.15138902046611451e-5 * SOLAR_MASS
];

function energy(
    xs: number[],
    ys: number[],
    zs: number[],
    vxs: number[],
    vys: number[],
    vzs: number[]
): number {
    let e = 0.0;

    for (let i = 0; i < 5; i++) {
        const mi = masses[i];
        const vx = vxs[i];
        const vy = vys[i];
        const vz = vzs[i];

        e += 0.5 * mi * (vx * vx + vy * vy + vz * vz);

        for (let j = i + 1; j < 5; j++) {
            const dx = xs[i] - xs[j];
            const dy = ys[i] - ys[j];
            const dz = zs[i] - zs[j];
            const distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
            e -= mi * masses[j] / distance;
        }
    }

    return e;
}

