const limit = Number.parseInt(proc.argv[2], 10);

function gcdSmallBig(small: bigint, big: bigint): bigint {
    let a = small < 0n ? -small : small;
    if (a === 0n) return big < 0n ? -big : big;

    let b = big % a;
    if (b < 0n) b = -b;

    while (b !== 0n) {
        const remainder = a % b;
        a = b;
        b = remainder;
    }
    return a;
}

let q = 1n;
let r = 0n;
let t = 1n;
let k = 1n;
let nextDigit = 3n;
let l = 3n;

let emitted = 0;
let line = "";
const output: string[] = [];

while (emitted < limit) {
    if (4n * q + r - t < nextDigit * t) {
        line += nextDigit.toString();
        emitted++;

        const divisor = gcdSmallBig(10n, t);
        const multiplier = 10n / divisor;

        q *= multiplier;
        r = (r - nextDigit * t) * multiplier;
        t /= divisor;

        nextDigit = (3n * q + r) / t;

        if (line.length === 10 || emitted === limit) {
            output.push(
                line.padEnd(10, " ") + "\t:" + emitted.toString() + "\n"
            );
            line = "";
        }
    } else {
        const rawQ = q * k;
        const commonWithL = gcdSmallBig(l, rawQ);
        const reducedL = l / commonWithL;

        q = rawQ / commonWithL;
        r = (2n * q * commonWithL / k + r) * reducedL;
        t *= reducedL;

        let common = gcdSmallBig(k, q);
        if (common > 1n) common = gcdSmallBig(common, r);
        if (common > 1n) common = gcdSmallBig(common, t);

        if (common > 1n) {
            q /= common;
            r /= common;
            t /= common;
        }

        k++;
        l += 2n;
        nextDigit = (3n * q + r) / t;
    }
}

proc.stdout.write(output.join(""));
