const complement = new Uint8Array(256);
for (let i = 0; i < 256; i++) complement[i] = i;

const bases = "ACBDGHKMNSRUTWVY";
const complements = "TGVHCDMKNSYAAWBR";

for (let i = 0; i < bases.length; i++) {
    const upper = bases.charCodeAt(i);
    const lower = upper + 32;
    const mapped = complements.charCodeAt(i);

    complement[upper] = mapped;
    complement[lower] = mapped;
}

function reverseComplement(start: number, end: number): void {
    let left = start;
    let right = end - 1;

    while (left <= right) {
        while (left <= right && (data[left] === 10 || data[left] === 13)) {
            left++;
        }
        while (left <= right && (data[right] === 10 || data[right] === 13)) {
            right--;
        }

        if (left > right) break;

        const leftBase = data[left];
        const rightBase = data[right];

        data[left] = complement[rightBase];
        data[right] = complement[leftBase];

        left++;
        right--;
    }
}

let position = 0;
let sequenceStart = -1;

while (position < data.length) {
    const atLineStart = position === 0 || data[position - 1] === 10;

    if (atLineStart && data[position] === 62) { // '>'
        if (sequenceStart >= 0) {
            reverseComplement(sequenceStart, position);
        }

        while (position < data.length && data[position] !== 10) {
            position++;
        }

        if (position < data.length) position++;
        sequenceStart = position;
    } else {
        position++;
    }
}

if (sequenceStart >= 0) {
    reverseComplement(sequenceStart, data.length);
}

process.stdout.write(data);
