function multiplyAv(input: Float64Array, output: Float64Array): void {
    for (let i = 0; i < n; i++) {
        let sum = 0.0;
        let denominator = (i * (i + 3)) / 2 + 1;
        let increment = i + 1;

        for (let j = 0; j < n; j++) {
            sum += input[j] / denominator;
            denominator += increment;
            increment++;
        }

        output[i] = sum;
    }
}

function multiplyAtv(input: Float64Array, output: Float64Array): void {
    for (let i = 0; i < n; i++) {
        let sum = 0.0;
        let denominator = (i * (i + 1)) / 2 + 1;
        let increment = i + 2;

        for (let j = 0; j < n; j++) {
            sum += input[j] / denominator;
            denominator += increment;
            increment++;
        }

        output[i] = sum;
    }
}

